def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = set(v for row in grid for v in row if v != bg)
    for color in colors:
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for dr, dc in ((1, 1), (1, -1)):
            for r, c in pts:
                if (r + dr, c + dc) not in pts:
                    continue
                # Extend each pair along its diagonal, stopping at existing markers.
                for rr, cc, sr, sc in ((r - dr, c - dc, -dr, -dc),
                                       (r + 2 * dr, c + 2 * dc, dr, dc)):
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out

